(1089101, 132007, 22310, '<td valign="top">Good shot, 6.  I would have given higher but her upper body looks a little washed out and there is a halo around her head.</td>', 'Good shot, 6.  I would have given higher but her upper body looks a little washed out and there is a halo around her head.', '2005-01-03 16:47:55.000000', NULL, 1),
(1089109, 132873, 22310, '<td valign="top">I like the composition.  Nice choice of the DOF.  Great detail on the black coat, 7.  I would have given higher if more of the face was visible but hard to expect perfection from a candid.</td>', 'I like the composition.  Nice choice of the DOF.  Great detail on the black coat, 7.  I would have given higher if more of the face was visible but hard to expect perfection from a candid.', '2005-01-03 16:50:02.000000', NULL, 1),
