(1089228, 131445, 11295, '<td valign="top">The selective desat really works here.</td>', 'The selective desat really works here.', '2005-01-03 17:32:13.000000', NULL, 1),
(1089236, 132890, 11295, '<td valign="top">Somehow, desaturating the main subject(s) doesn''t work for me here... I''m more drawn to the background, and that takes away from the shot IMO. As a suggestion, I''d have gone with a shallower DOF and left the colour intact. Still, fits the challenge well.</td>', 'Somehow, desaturating the main subject(s) doesn''t work for me here... I''m more drawn to the background, and that takes away from the shot IMO. As a suggestion, I''d have gone with a shallower DOF and left the colour intact. Still, fits the challenge well.', '2005-01-03 17:35:33.000000', NULL, 1),
(1089240, 132191, 11295, '<td valign="top">Everything works here, and I love the shot. Only thing is that it''s off kilter a little with horizontal alignment. For me, that''s distracting, and takes away from the mood.</td>', 'Everything works here, and I love the shot. Only thing is that it''s off kilter a little with horizontal alignment. For me, that''s distracting, and takes away from the mood.', '2005-01-03 17:38:21.000000', NULL, 1),
