(1089923, 132224, 9906, '<td valign="top">Dang, can''t see the camera!  ;-)<br/>TC</td>', 'Dang, can''t see the camera!  ;-)TC', '2005-01-03 23:57:55.000000', NULL, 1),
(1089925, 131760, 9906, '<td valign="top">Very nice soft focus effect.  How did you achieve this?  Please tell us after the challenge!  Great tonality too.  Gives it a more old timey feel which fits in well with the subject.  Your title leads one to believe this is a sad time, but the feel of the shot doesn''t show it.  Makes me wonder about the cultures involved...<br/>TC</td>', 'Very nice soft focus effect.  How did you achieve this?  Please tell us after the challenge!  Great tonality too.  Gives it a more old timey feel which fits in well with the subject.  Your title leads one to believe this is a sad time, but the feel of the shot doesn''t show it.  Makes me wonder about the cultures involved...TC', '2005-01-04 00:00:35.000000', NULL, 1),
(1089929, 132342, 9906, '<td valign="top">Awesome lighting.  Day break or sun set?<br/>TC</td>', 'Awesome lighting.  Day break or sun set?TC', '2005-01-04 00:01:40.000000', NULL, 1),
(1089931, 132569, 9906, '<td valign="top">Ooooh....   You almost broke the but crack rule... :-O<br/>Which one is the leech bait?  :-)<br/>TC</td>', 'Ooooh....   You almost broke the but crack rule... :-OWhich one is the leech bait?  :-)TC', '2005-01-04 00:03:45.000000', NULL, 1),
(1089932, 132799, 26313, '<td valign="top">Brilliant idea!<br/>Would be better without the light pole though, or at least with the pole vertical.<br/><br/><i>Message edited by author 2005-01-18 17:46:06.</i></td>', 'Brilliant idea!Would be better without the light pole though, or at least with the pole vertical.', '2005-01-04 00:04:31.000000', '2005-01-18 17:46:06.000000', 1),
(1089934, 131832, 9906, '<td valign="top">Funny shot!  Funny title!  Great colors and exposure!  Great example of bokeh.  My only problem with the shot is that I''m a traditionalist as far as the term candid is concerned and have to mark down a point for lack of people...<br/>TC</td>', 'Funny shot!  Funny title!  Great colors and exposure!  Great example of bokeh.  My only problem with the shot is that I''m a traditionalist as far as the term candid is concerned and have to mark down a point for lack of people...TC', '2005-01-04 00:05:54.000000', NULL, 1),
(1089936, 132724, 9906, '<td valign="top">Classic!  Too bad your snow is blown out.  What a hard exposure to get quickly.  Nicely done though.  Did you at least throw they guy a buck?<br/>TC</td>', 'Classic!  Too bad your snow is blown out.  What a hard exposure to get quickly.  Nicely done though.  Did you at least throw they guy a buck?TC', '2005-01-04 00:06:53.000000', NULL, 1),
(1089937, 132374, 9906, '<td valign="top">Nice shot.  Your lighting is a little flat but not too bad.<br/>TC</td>', 'Nice shot.  Your lighting is a little flat but not too bad.TC', '2005-01-04 00:07:59.000000', NULL, 1),
(1089938, 131109, 26313, '<td valign="top">Would maybe be better a little darker with a little more contrast I think.</td>', 'Would maybe be better a little darker with a little more contrast I think.', '2005-01-04 00:09:18.000000', NULL, 1),
(1089939, 132074, 9906, '<td valign="top">Something about this LOOKS artificial to me.  Did you play around with the feather and background colors?  You have some kind of artifact around the head covering that makes it look a little funny...  Perhaps from over sharpening?  Sorry if I''m assuming too much just sayin'' what I see...<br/>TC</td>', 'Something about this LOOKS artificial to me.  Did you play around with the feather and background colors?  You have some kind of artifact around the head covering that makes it look a little funny...  Perhaps from over sharpening?  Sorry if I''m assuming too much just sayin'' what I see...TC', '2005-01-04 00:11:14.000000', NULL, 1),
(1089940, 131860, 9906, '<td valign="top">This is a great capture of a moment.  He looks so melencholy.  Makes me wonder what he''s thinking!<br/>TC</td>', 'This is a great capture of a moment.  He looks so melencholy.  Makes me wonder what he''s thinking!TC', '2005-01-04 00:12:55.000000', NULL, 1),
(1089941, 132740, 26313, '<td valign="top">Candid it might be, but focused it''s not. Also might be nice to get the whole head in the shot.<br/>Nice mouse pad though!</td>', 'Candid it might be, but focused it''s not. Also might be nice to get the whole head in the shot.Nice mouse pad though!', '2005-01-04 00:13:40.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1089946, 132442, 15811, '<td valign="top">I really like the shot here.  My choice for a ribbon.  The selective desaturation isn''t really necessary here to ''help'' the photo as it is the mood that you''ve captured that makes it what it is -- it doesn''t take anything away though in my opinion either although it is just a bit distracting.<br/> <br/>Great composition -- the crop is just tight enough to get a nice close look at the subject, and just far enough away to see everything that you need to.<br/> <br/>The image has black, white, and everything inbetween -- a really well thought out image and very much deserving of a ribbon.  Nice work! 10</td>', 'I really like the shot here.  My choice for a ribbon.  The selective desaturation isn''t really necessary here to ''help'' the photo as it is the mood that you''ve captured that makes it what it is -- it doesn''t take anything away though in my opinion either although it is just a bit distracting. Great composition -- the crop is just tight enough to get a nice close look at the subject, and just far enough away to see everything that you need to. The image has black, white, and everything inbetween -- a really well thought out image and very much deserving of a ribbon.  Nice work! 10', '2005-01-04 00:19:22.000000', NULL, 1),
(1089951, 131378, 9906, '<td valign="top">This looks like one of those shots that one so wants to save but may be unsaveable...  You have an obviously very precious moment captured.  I would try and work the shot too.  However, you have a glowing artifact around most of the people.  This leads me to believe that you tried to brighten the dark areas without blowing out the light areas.  I know because I get this glowing artifact when I try to do this with some shots.  Wish I knew how to avoid it...  The background also looks like you tried to impose an artificially shallow DOF on the shot to isolate the main subjects.  Normally I would say the shot is too busy but that doesn''t feel like the case with this shot.  You have a scene that is busy and looks like it should be!  Nice attempt.  Please don''t think I''m being harsh.  If I didn''t see potential, I wouldn''t have bothered typing!<br/>TC</td>', 'This looks like one of those shots that one so wants to save but may be unsaveable...  You have an obviously very precious moment captured.  I would try and work the shot too.  However, you have a glowing artifact around most of the people.  This leads me to believe that you tried to brighten the dark areas without blowing out the light areas.  I know because I get this glowing artifact when I try to do this with some shots.  Wish I knew how to avoid it...  The background also looks like you tried to impose an artificially shallow DOF on the shot to isolate the main subjects.  Normally I would say the shot is too busy but that doesn''t feel like the case with this shot.  You have a scene that is busy and looks like it should be!  Nice attempt.  Please don''t think I''m being harsh.  If I didn''t see potential, I wouldn''t have bothered typing!TC', '2005-01-04 00:24:18.000000', NULL, 1),
(1089954, 132888, 9906, '<td valign="top">Grandmother and Grand daughter?  Great emotion in the face of the older lady!  You can tell that she loves the younger.  You can see it in her expression!  Great capture.<br/>TC</td>', 'Grandmother and Grand daughter?  Great emotion in the face of the older lady!  You can tell that she loves the younger.  You can see it in her expression!  Great capture.TC', '2005-01-04 00:25:28.000000', NULL, 1),
(1089958, 132692, 9906, '<td valign="top">Great shot, but IMHO it doesn''t meet the challenge.  I''m a little traditional when it comes to the term candid and feel that it needs to have people in it.<br/>TC</td>', 'Great shot, but IMHO it doesn''t meet the challenge.  I''m a little traditional when it comes to the term candid and feel that it needs to have people in it.TC', '2005-01-04 00:26:31.000000', NULL, 1),
(1089959, 132720, 25464, '<td valign="top">Emotion captured.  Good focus.  The color seems a little flat, but overall good shot.</td>', 'Emotion captured.  Good focus.  The color seems a little flat, but overall good shot.', '2005-01-04 00:26:55.000000', NULL, 1),
(1089960, 132453, 9906, '<td valign="top">Nice butt???<br/>TC</td>', 'Nice butt???TC', '2005-01-04 00:27:03.000000', NULL, 1),
(1089962, 132380, 25464, '<td valign="top">The lines and colors are interesting as well as the diversity of the group with common interest.  Good eye.</td>', 'The lines and colors are interesting as well as the diversity of the group with common interest.  Good eye.', '2005-01-04 00:27:44.000000', NULL, 1),
(1089964, 132714, 9906, '<td valign="top">This is really nice!  Awesome capture.  Great choice of going B/W with it.  Don''t know what it is that sets it apart but I will try and come back and refine this comment.<br/>Kudos<br/>TC</td>', 'This is really nice!  Awesome capture.  Great choice of going B/W with it.  Don''t know what it is that sets it apart but I will try and come back and refine this comment.KudosTC', '2005-01-04 00:28:20.000000', NULL, 1),
(1089966, 132675, 25464, '<td valign="top">I don''t know if the soft focus was intentional here, but I think it is a bit too soft for this shot.  The black and white is nice, and the poster in the background is interesting to me, but I don''t really see any emotion displayed.  The bright spot in the center of the table is a bit of a distraction as well.</td>', 'I don''t know if the soft focus was intentional here, but I think it is a bit too soft for this shot.  The black and white is nice, and the poster in the background is interesting to me, but I don''t really see any emotion displayed.  The bright spot in the center of the table is a bit of a distraction as well.', '2005-01-04 00:29:27.000000', NULL, 1),
(1089968, 131537, 25464, '<td valign="top">I like the angle in relation to the motion of the bus or train.  The lighting is interesting as well.</td>', 'I like the angle in relation to the motion of the bus or train.  The lighting is interesting as well.', '2005-01-04 00:30:53.000000', NULL, 1),
(1089970, 132431, 9906, '<td valign="top">Somebody is having a grand time here!  Good capture of the emotion!<br/>TC</td>', 'Somebody is having a grand time here!  Good capture of the emotion!TC', '2005-01-04 00:31:50.000000', NULL, 1),
(1089973, 131708, 25464, '<td valign="top">Gorgeous color and perfect soft focus.  Great smile.</td>', 'Gorgeous color and perfect soft focus.  Great smile.', '2005-01-04 00:34:31.000000', NULL, 1),
(1089974, 132007, 10080, '<td valign="top">Its a great shot! The halo around her head realy sticks out here! Still..nice job, 8</td>', 'Its a great shot! The halo around her head realy sticks out here! Still..nice job, 8', '2005-01-04 00:37:19.000000', NULL, 1),
(1089975, 132760, 25464, '<td valign="top">This is one time that I think the harshness of the lighting adds to the photo.  This shot is filled with emotion and I love the rich tones as well.  I think it might have been slightly improved with a little looser crop keeping the elbow in the frame and leaving a bit more empty space to the back of the subject.  I think that might have emphasized the look of complete concentration.</td>', 'This is one time that I think the harshness of the lighting adds to the photo.  This shot is filled with emotion and I love the rich tones as well.  I think it might have been slightly improved with a little looser crop keeping the elbow in the frame and leaving a bit more empty space to the back of the subject.  I think that might have emphasized the look of complete concentration.', '2005-01-04 00:37:41.000000', NULL, 1),
(1089976, 131781, 25464, '<td valign="top">Very nice.  Great capture.</td>', 'Very nice.  Great capture.', '2005-01-04 00:38:22.000000', NULL, 1),
(1089981, 132849, 25464, '<td valign="top">Did they both eat something bad????  Very cute and boy do they look alike.</td>', 'Did they both eat something bad????  Very cute and boy do they look alike.', '2005-01-04 00:41:00.000000', NULL, 1),
(1089982, 132345, 25464, '<td valign="top">Feet in the frame, and this would have been pretty perfect.  Still a nice capture.  Great emotion conveyed.</td>', 'Feet in the frame, and this would have been pretty perfect.  Still a nice capture.  Great emotion conveyed.', '2005-01-04 00:41:47.000000', NULL, 1),
(1089985, 132007, 25464, '<td valign="top">This is a very nice shot that just screams rebellion.  Mood, black and white rendering, expression, stance, all perfect.  I think the only thing I can find to pick on is the stark white sky.  Bumping to 10.</td>', 'This is a very nice shot that just screams rebellion.  Mood, black and white rendering, expression, stance, all perfect.  I think the only thing I can find to pick on is the stark white sky.  Bumping to 10.', '2005-01-04 00:54:00.000000', NULL, 1),
(1089988, 132636, 25464, '<td valign="top">Absolutely great!  What a character!  Nice expression, great composition. Lighting is perfect.  This could be a winner in my opinion. 9.</td>', 'Absolutely great!  What a character!  Nice expression, great composition. Lighting is perfect.  This could be a winner in my opinion. 9.', '2005-01-04 00:54:34.000000', NULL, 1),
(1089996, 132482, 30861, '<td valign="top">There''s a lot to like in this image, but a number of things are detracting as well.<br/> <br/>Good points: sharpness of, and expression on, face. It''s a nice study of concentration. Also the tonalities are rich, it''s a good B/W conversion, mellow and smooth.<br/> <br/>The croppung seems off to me; the truncated head is arbitrary, the space below the elbow is not doing anything. I tried cropping most of that lower space off and bringing the right edge in so I couldn''t see any of the "77" in the background, and this was a tighhter &amp; stronger crop to my eyes. Often, with candids, the crop will make or break the image.<br/> <br/>It''s unfortunate that the mechanic''s hand and the rag are not also sharp. The hand, especially, could be a vital part of the image, but it''s not. It looks like if you''d pul;led focus forward a bit, your DOF would have been ample to have had hand and face both sharp.<br/> <br/>Finally, and this is critical, the wall behind the head is too bright, and it is pulling my eye in the wrong direction; I want to be following the direction of his gaze, but the eyetrap in upper left is oulling me the other way.<br/></td>', 'There''s a lot to like in this image, but a number of things are detracting as well. Good points: sharpness of, and expression on, face. It''s a nice study of concentration. Also the tonalities are rich, it''s a good B/W conversion, mellow and smooth. The croppung seems off to me; the truncated head is arbitrary, the space below the elbow is not doing anything. I tried cropping most of that lower space off and bringing the right edge in so I couldn''t see any of the "77" in the background, and this was a tighhter & stronger crop to my eyes. Often, with candids, the crop will make or break the image. It''s unfortunate that the mechanic''s hand and the rag are not also sharp. The hand, especially, could be a vital part of the image, but it''s not. It looks like if you''d pul;led focus forward a bit, your DOF would have been ample to have had hand and face both sharp. Finally, and this is critical, the wall behind the head is too bright, and it is pulling my eye in the wrong direction; I want to be following the direction of his gaze, but the eyetrap in upper left is oulling me the other way.', '2005-01-04 01:14:29.000000', NULL, 1),
(1090000, 132683, 30861, '<td valign="top">Remarkable, out-of-the-box take on the challenge. There''s a slightly distracting sliver of background showing upper left that should be cropped out. Possibly crop down also so the intersection of windowframe and extended arm of rider is at the top, not much of a crop. The critical sharpness in the reflection juxtaposed with the blurry reaility outside the window makes this picture.</td>', 'Remarkable, out-of-the-box take on the challenge. There''s a slightly distracting sliver of background showing upper left that should be cropped out. Possibly crop down also so the intersection of windowframe and extended arm of rider is at the top, not much of a crop. The critical sharpness in the reflection juxtaposed with the blurry reaility outside the window makes this picture.', '2005-01-04 01:17:55.000000', NULL, 1),
(1090004, 132002, 30861, '<td valign="top">This is a fabulous candid. I think the crop is a littlke too horizontal. I''ve tried massaging it and to my eye it works better if we crop the left so the bright hand at bottom left is cropped out. If you''re not going to do that, certainly tone it down a little; that "hand" is a real eyetrap.<br/> <br/>As an image, this works very well exactly as it is, and i am ranking it high. However, to my way of thinking "obvious" post-processing (like the extremely selective desaturation here) tends to move an image away from a "true" candid, by making it obvious that the "hand of man" was involved in the image.</td>', 'This is a fabulous candid. I think the crop is a littlke too horizontal. I''ve tried massaging it and to my eye it works better if we crop the left so the bright hand at bottom left is cropped out. If you''re not going to do that, certainly tone it down a little; that "hand" is a real eyetrap. As an image, this works very well exactly as it is, and i am ranking it high. However, to my way of thinking "obvious" post-processing (like the extremely selective desaturation here) tends to move an image away from a "true" candid, by making it obvious that the "hand of man" was involved in the image.', '2005-01-04 01:22:38.000000', NULL, 1),
(1090008, 132849, 30861, '<td valign="top">Exceptionally beautiful image. The more I look at it, the more details I see that interest me. Love the squinting right eye of the father, the detail of the wrappers, the fine hair detail on the foreheads, the perfect arc of hood around ear, etc etc.<br/> <br/>The image is sl;ightly flawed by overuse of the USM, whch has produced a halo around the figures where the pixels contrast with the background. This can be avoided by using a selection mask to select out the figures alone, then shrinking the mask by 2 pixels all around, which woukld leave no extreme contrast at the edges of the mask and generate no halo.</td>', 'Exceptionally beautiful image. The more I look at it, the more details I see that interest me. Love the squinting right eye of the father, the detail of the wrappers, the fine hair detail on the foreheads, the perfect arc of hood around ear, etc etc. The image is sl;ightly flawed by overuse of the USM, whch has produced a halo around the figures where the pixels contrast with the background. This can be avoided by using a selection mask to select out the figures alone, then shrinking the mask by 2 pixels all around, which woukld leave no extreme contrast at the edges of the mask and generate no halo.', '2005-01-04 01:26:58.000000', NULL, 1),
(1090009, 132720, 30861, '<td valign="top">There is just a world of emotion in this. A true candid. Marvelous shape formed in the negative space between foreheads and noses, as if their whole world were there. Lovely how the noses don''t-quite-kiss. I wish her ear were sharper, and perhaps a little green cast removed from the image. Wonderful picture.</td>', 'There is just a world of emotion in this. A true candid. Marvelous shape formed in the negative space between foreheads and noses, as if their whole world were there. Lovely how the noses don''t-quite-kiss. I wish her ear were sharper, and perhaps a little green cast removed from the image. Wonderful picture.', '2005-01-04 01:29:23.000000', NULL, 1),
(1090013, 131865, 30861, '<td valign="top">In this example, the selective desaturation looks much more natural than in most cases. I think the figure behind the pole should be desatted also, though. The image is marred by not being rotated ccw to a truer vertical; it''s so close that it looks accidental that it''s NOT vertically aligned. I could wish for a little more sharpness too. A fine, gritty slice-of-the-streets.</td>', 'In this example, the selective desaturation looks much more natural than in most cases. I think the figure behind the pole should be desatted also, though. The image is marred by not being rotated ccw to a truer vertical; it''s so close that it looks accidental that it''s NOT vertically aligned. I could wish for a little more sharpness too. A fine, gritty slice-of-the-streets.', '2005-01-04 01:32:01.000000', NULL, 1),
(1090017, 132832, 30861, '<td valign="top">Fine expression captured. Jester is apparently using a cellphone, pity we can''t see it. I wish the point of critical sharpness were on the woman''s face and the jester were slightly out of focus. A strong entry.</td>', 'Fine expression captured. Jester is apparently using a cellphone, pity we can''t see it. I wish the point of critical sharpness were on the woman''s face and the jester were slightly out of focus. A strong entry.', '2005-01-04 01:33:26.000000', NULL, 1),
(1090019, 131377, 30861, '<td valign="top">Immaculate in every respect. Clone away the tiny, bright dot center right? The red hat and it''s associated ear are simply wonderful.</td>', 'Immaculate in every respect. Clone away the tiny, bright dot center right? The red hat and it''s associated ear are simply wonderful.', '2005-01-04 01:34:43.000000', NULL, 1),
(1090020, 131238, 30861, '<td valign="top">I LOVE this for the genre of "accidental snaps", it is stronger precisely because it is so obviously spontaneous and irreprodicible. The overall composition is remarkably wacky. You obviously cropped this; I''d love to see the original. A solid high score from me, I hope others see what I see.</td>', 'I LOVE this for the genre of "accidental snaps", it is stronger precisely because it is so obviously spontaneous and irreprodicible. The overall composition is remarkably wacky. You obviously cropped this; I''d love to see the original. A solid high score from me, I hope others see what I see.', '2005-01-04 01:36:40.000000', NULL, 1),
(1090022, 132363, 30861, '<td valign="top">This is just SO dine, the expressions, the tonal control, the overall human richness of it. The face in the mirror TOTALLY takes it over the top. Fine candid!</td>', 'This is just SO dine, the expressions, the tonal control, the overall human richness of it. The face in the mirror TOTALLY takes it over the top. Fine candid!', '2005-01-04 01:37:53.000000', NULL, 1),
(1090026, 131529, 30861, '<td valign="top">Extraordinary overall impact. I wish more work had been done to separate the figures a tad from their dark surrounds. If we could just SZEE his arms where they cross the seat bolsters, the hands would be a much stronger element.</td>', 'Extraordinary overall impact. I wish more work had been done to separate the figures a tad from their dark surrounds. If we could just SZEE his arms where they cross the seat bolsters, the hands would be a much stronger element.', '2005-01-04 01:39:56.000000', NULL, 1),
(1090027, 132760, 30861, '<td valign="top">Rich and evocative, beautifully composed. Separation of hair from BG on left is fantastic. Perhaps use healing brush to mute the nose higlights slightly? Very strong image.</td>', 'Rich and evocative, beautifully composed. Separation of hair from BG on left is fantastic. Perhaps use healing brush to mute the nose higlights slightly? Very strong image.', '2005-01-04 01:41:37.000000', NULL, 1),
(1090028, 132715, 30861, '<td valign="top">Simply striking. Be even more so if his (her?) hair separated a tad better from BG. I''d have toned down the chain (?) in the center bottom a couple stops too, it''s an eyetrap.</td>', 'Simply striking. Be even more so if his (her?) hair separated a tad better from BG. I''d have toned down the chain (?) in the center bottom a couple stops too, it''s an eyetrap.', '2005-01-04 01:43:12.000000', NULL, 1),
(1090029, 132106, 30861, '<td valign="top">Lovely. I wish we had a bit more on the top, that''s a pretty tight fit there.</td>', 'Lovely. I wish we had a bit more on the top, that''s a pretty tight fit there.', '2005-01-04 01:44:20.000000', NULL, 1),
(1090030, 132695, 30861, '<td valign="top">Very nice. I''d think about brushing out the random highlights between the two figures on right. These are just tiny distractions. More critically, the very bright highlights on her hair are pulling the eye the wrong way; we really want our focus drawn to the hand holding the piece. I''d tone those way down, to visually contain the drama of the action.</td>', 'Very nice. I''d think about brushing out the random highlights between the two figures on right. These are just tiny distractions. More critically, the very bright highlights on her hair are pulling the eye the wrong way; we really want our focus drawn to the hand holding the piece. I''d tone those way down, to visually contain the drama of the action.', '2005-01-04 01:46:28.000000', NULL, 1),
(1090032, 132250, 30861, '<td valign="top">Wonderful compositiona nd expression, marred somewhat by less-than-critical visual acuity and a tad too much contrast.</td>', 'Wonderful compositiona nd expression, marred somewhat by less-than-critical visual acuity and a tad too much contrast.', '2005-01-04 01:47:41.000000', NULL, 1),
(1090035, 132634, 30861, '<td valign="top">This is like a "Bingo!" picture. Selective desaturation works here because it''s natural-feeling.</td>', 'This is like a "Bingo!" picture. Selective desaturation works here because it''s natural-feeling.', '2005-01-04 01:49:06.000000', NULL, 1),
(1090036, 132595, 30861, '<td valign="top">Very strong environmental candid. Would benefit from a more muted, softer tonal range and more sparing use of the sharpening filters, I think. There''s lots going on, lots of stories to read. Good work!</td>', 'Very strong environmental candid. Would benefit from a more muted, softer tonal range and more sparing use of the sharpening filters, I think. There''s lots going on, lots of stories to read. Good work!', '2005-01-04 01:50:39.000000', NULL, 1),
(1090037, 132567, 30861, '<td valign="top">Nice! I''d rate it higher if it were crisper. A solid image, a strong score.</td>', 'Nice! I''d rate it higher if it were crisper. A solid image, a strong score.', '2005-01-04 01:51:37.000000', NULL, 1),
(1090038, 131510, 30861, '<td valign="top">A pity you didn''t have critical focus on this. Use of sharpening filter is too obvious and not especially effective anyway in this case. A very evocative moment.</td>', 'A pity you didn''t have critical focus on this. Use of sharpening filter is too obvious and not especially effective anyway in this case. A very evocative moment.', '2005-01-04 01:52:44.000000', NULL, 1),
(1090040, 131382, 30861, '<td valign="top">Sweetly composed. I love the 3 entirely different orientations of the heads. I wish the focus were better.</td>', 'Sweetly composed. I love the 3 entirely different orientations of the heads. I wish the focus were better.', '2005-01-04 01:53:56.000000', NULL, 1),
(1090041, 132405, 30861, '<td valign="top">Striking composition and colors, not all that "candid" feeling though. Looks like sharpness filters were overapplied.</td>', 'Striking composition and colors, not all that "candid" feeling though. Looks like sharpness filters were overapplied.', '2005-01-04 01:55:11.000000', NULL, 1),
(1090042, 132752, 30861, '<td valign="top">One of the best of the "animal candids", by far. There''s a real sense of interaction, of "emotion" if you will. Lovely tonalities.</td>', 'One of the best of the "animal candids", by far. There''s a real sense of interaction, of "emotion" if you will. Lovely tonalities.', '2005-01-04 01:56:06.000000', NULL, 1),
(1090043, 132342, 30861, '<td valign="top">A striking image. Sky artefacts downgrade this in my eyes.</td>', 'A striking image. Sky artefacts downgrade this in my eyes.', '2005-01-04 01:57:15.000000', NULL, 1),
(1090044, 131708, 30861, '<td valign="top">It''s a beautiful picture, but it''s overworked to the degree that it no longer feels candid, even though I''m sure it was. As long as you''re working it so hard, why not whiten the teeth a tad? Lovely image, but for me it doesn''t work directly to the challenge.</td>', 'It''s a beautiful picture, but it''s overworked to the degree that it no longer feels candid, even though I''m sure it was. As long as you''re working it so hard, why not whiten the teeth a tad? Lovely image, but for me it doesn''t work directly to the challenge.', '2005-01-04 01:58:39.000000', NULL, 1),
(1090045, 131189, 30861, '<td valign="top">Deceptively appealing. I wish you''d applied a little local adjustment to the man, to make him render more up-tone.</td>', 'Deceptively appealing. I wish you''d applied a little local adjustment to the man, to make him render more up-tone.', '2005-01-04 01:59:43.000000', NULL, 1),
(1090048, 132374, 30861, '<td valign="top">REALLY nice pic. It''s a slight flaw that the face, the center of this composition physically and emotionally, seems less sharp than the pig and the backfrop cloths. Note that his hand is sharper than his face The eyes are priceless.</td>', 'REALLY nice pic. It''s a slight flaw that the face, the center of this composition physically and emotionally, seems less sharp than the pig and the backfrop cloths. Note that his hand is sharper than his face The eyes are priceless.', '2005-01-04 02:01:45.000000', NULL, 1),
(1090052, 132074, 30861, '<td valign="top">This would be MUCH stronger if the right edge were cropped in to bring the image back to a more conventional width/height ratio. As it is, the image is almost precisely bisected into all subject / all BG.</td>', 'This would be MUCH stronger if the right edge were cropped in to bring the image back to a more conventional width/height ratio. As it is, the image is almost precisely bisected into all subject / all BG.', '2005-01-04 02:05:44.000000', NULL, 1),
(1090054, 132873, 30861, '<td valign="top">strong and evocative, doesn''t call attention to itself in any way, lets the scene be what it is.</td>', 'strong and evocative, doesn''t call attention to itself in any way, lets the scene be what it is.', '2005-01-04 02:06:32.000000', NULL, 1),
(1090056, 132718, 30861, '<td valign="top">sweet and eerie at the same time. Lower right seems too bright to me, and possibly the brush hand as well.</td>', 'sweet and eerie at the same time. Lower right seems too bright to me, and possibly the brush hand as well.', '2005-01-04 02:07:31.000000', NULL, 1),
(1090059, 132121, 30861, '<td valign="top">This is one of those very fine images that just doesn''t "feel" candid to me. I''m sure it was, but it doesn''t feel that way to me, and in this challenge I am voting in favor of immediacy over calculation.</td>', 'This is one of those very fine images that just doesn''t "feel" candid to me. I''m sure it was, but it doesn''t feel that way to me, and in this challenge I am voting in favor of immediacy over calculation.', '2005-01-04 02:08:53.000000', NULL, 1),
(1090060, 132893, 30861, '<td valign="top">A striking image, but not to my mind truly a "candid"; It''s an image that is based on a person, and the person is unaware youa re shooting, but it lacks the emotional quotient that defines "candid" in my mind.</td>', 'A striking image, but not to my mind truly a "candid"; It''s an image that is based on a person, and the person is unaware youa re shooting, but it lacks the emotional quotient that defines "candid" in my mind.', '2005-01-04 02:10:27.000000', NULL, 1),
(1090061, 132521, 30861, '<td valign="top">There''s a lot tolike here, but the very arbitray selective desaturation takes this out of the candid category in my mind. The finger under his chin is oddly distracting. It would be far less so if the BG hadn''t been desatted.</td>', 'There''s a lot tolike here, but the very arbitray selective desaturation takes this out of the candid category in my mind. The finger under his chin is oddly distracting. It would be far less so if the BG hadn''t been desatted.', '2005-01-04 02:12:36.000000', NULL, 1),
(1090062, 132745, 30861, '<td valign="top">That''s an extraordinary depiction of "ennui". Unfortunately the point of critical focus is the hands, where it might better be the eyes.</td>', 'That''s an extraordinary depiction of "ennui". Unfortunately the point of critical focus is the hands, where it might better be the eyes.', '2005-01-04 02:13:57.000000', NULL, 1),
(1090065, 131109, 30861, '<td valign="top">Overlap of figure and utility pole is unfortunate. Picture would breathe better with less foreground and more on top. Possibly if you''d panned more to the left (the wayhe''s looking( and positioned him in the right third of the frame, you''d have an image that told a stronger story of waiting. Very nice tonalities.</td>', 'Overlap of figure and utility pole is unfortunate. Picture would breathe better with less foreground and more on top. Possibly if you''d panned more to the left (the wayhe''s looking( and positioned him in the right third of the frame, you''d have an image that told a stronger story of waiting. Very nice tonalities.', '2005-01-04 02:16:05.000000', NULL, 1),
(1090066, 131832, 10658, '<td valign="top">That is definitely a candid moment!  10</td>', 'That is definitely a candid moment!  10', '2005-01-04 02:18:23.000000', NULL, 1),
(1090067, 132345, 30861, '<td valign="top">Title makes this image. Excessive use of sharpening tools hurts it. One wonders, had you moved a tad to the left  could you have palced the foreground child more on the right side of the image relative to the background activity, and gotten a better dynamic?</td>', 'Title makes this image. Excessive use of sharpening tools hurts it. One wonders, had you moved a tad to the left  could you have palced the foreground child more on the right side of the image relative to the background activity, and gotten a better dynamic?', '2005-01-04 02:18:31.000000', NULL, 1),
(1090068, 131860, 30861, '<td valign="top">Sweet. Critical focus is on his right hand, where it would better be on his eyes, a very slight pull on the focus.</td>', 'Sweet. Critical focus is on his right hand, where it would better be on his eyes, a very slight pull on the focus.', '2005-01-04 02:19:32.000000', NULL, 1),
(1090069, 131570, 30861, '<td valign="top">Strong &amp; gritty. I like it, grain and all. His expression is extraordinary.</td>', 'Strong & gritty. I like it, grain and all. His expression is extraordinary.', '2005-01-04 02:20:24.000000', NULL, 1),
(1090070, 131286, 30861, '<td valign="top">Compositionally and thematically strong. Too contrasty, way overboard on the Unsharp Mask. I assume from this that the image wasn''t as sharply focised as you''d have liked, which is a pity.</td>', 'Compositionally and thematically strong. Too contrasty, way overboard on the Unsharp Mask. I assume from this that the image wasn''t as sharply focised as you''d have liked, which is a pity.', '2005-01-04 02:21:54.000000', NULL, 1),
(1090071, 132345, 10658, '<td valign="top">I thought about taking a picture just like this one!  Didn''t get the chance to do so though.  Looks good to me, the only think I might have done differently would have been taking a profile type photo of the kid looking at the other kids, something to show his expression I guess.  I dunno, I like the depth of field here so maybe this is better than my idea :)  My vote: 8</td>', 'I thought about taking a picture just like this one!  Didn''t get the chance to do so though.  Looks good to me, the only think I might have done differently would have been taking a profile type photo of the kid looking at the other kids, something to show his expression I guess.  I dunno, I like the depth of field here so maybe this is better than my idea :)  My vote: 8', '2005-01-04 02:22:11.000000', NULL, 1),
(1090073, 131692, 30861, '<td valign="top">sweeet... mute down the lower right corner a bit?</td>', 'sweeet... mute down the lower right corner a bit?', '2005-01-04 02:22:52.000000', NULL, 1),
(1090074, 132147, 30861, '<td valign="top">High marks for "feelgood"... Blah, static composition is hurting it, as are the unfortunate background trees. One would love to see what the kid''s feet are doing, if anything. Nice shot.</td>', 'High marks for "feelgood"... Blah, static composition is hurting it, as are the unfortunate background trees. One would love to see what the kid''s feet are doing, if anything. Nice shot.', '2005-01-04 02:24:27.000000', NULL, 1),
(1090075, 131972, 30861, '<td valign="top">a lot of spontaneity here. Pity the composition, the two dominat central elements, are conspiring to keep the dog from being a major player in the scene.if you were standing inthe exact same spot, pointing the cam the exact same way, and she had moved a few feet more to the left,a nd the dog were still doing his thing exactly like that, it might be a lot stronger.<br/> <br/>But then again, this is all about "candid", and you got no controlover these variables really. What it boils down to is, the best candids are a combination of vision and luck.<br/></td>', 'a lot of spontaneity here. Pity the composition, the two dominat central elements, are conspiring to keep the dog from being a major player in the scene.if you were standing inthe exact same spot, pointing the cam the exact same way, and she had moved a few feet more to the left,a nd the dog were still doing his thing exactly like that, it might be a lot stronger. But then again, this is all about "candid", and you got no controlover these variables really. What it boils down to is, the best candids are a combination of vision and luck.', '2005-01-04 02:27:12.000000', NULL, 1),
(1090076, 132888, 30861, '<td valign="top">I''d like this a LOT more if the focus were on the older woman''s face, not on her hand, and certainly not on the leather jacket, which is where it is sharpest here...</td>', 'I''d like this a LOT more if the focus were on the older woman''s face, not on her hand, and certainly not on the leather jacket, which is where it is sharpest here...', '2005-01-04 02:28:21.000000', NULL, 1),
(1090077, 131531, 30861, '<td valign="top">wonderful sense of dislocation in the midst of chaos. Pity the man in the parka, top dead center, isn''t showing motion blur liek those aroudn him. Image is marred by excessive use of USM on foreground figure: see haloing, especially on hat.</td>', 'wonderful sense of dislocation in the midst of chaos. Pity the man in the parka, top dead center, isn''t showing motion blur liek those aroudn him. Image is marred by excessive use of USM on foreground figure: see haloing, especially on hat.', '2005-01-04 02:30:07.000000', NULL, 1),
(1090080, 131225, 31307, '<td valign="top">Beautiful shot.  It''s interesting because the choice of black and white combined with the decor on the walls makes it seem like this shot could have been taken decades ago.  I like the way the hall is made to feel so big and the janitor so small.  It''s kind of like "This is his domain...to maintain."  Simutaneously he owns it and yet, in a way, is owned by it.  Great job.</td>', 'Beautiful shot.  It''s interesting because the choice of black and white combined with the decor on the walls makes it seem like this shot could have been taken decades ago.  I like the way the hall is made to feel so big and the janitor so small.  It''s kind of like "This is his domain...to maintain."  Simutaneously he owns it and yet, in a way, is owned by it.  Great job.', '2005-01-04 02:44:38.000000', NULL, 1),
(1090086, 132745, 31307, '<td valign="top">Good bokeh..oh, wait wrong challenge.  Really, though, the close depth of field enhances this photo.</td>', 'Good bokeh..oh, wait wrong challenge.  Really, though, the close depth of field enhances this photo.', '2005-01-04 02:47:23.000000', NULL, 1),
(1090089, 132363, 31307, '<td valign="top">I like how you can see others in the room through the mirror.  Mirrors, I''ve found, can be a great asset in making a shot more interesting.</td>', 'I like how you can see others in the room through the mirror.  Mirrors, I''ve found, can be a great asset in making a shot more interesting.', '2005-01-04 02:49:39.000000', NULL, 1),
(1090092, 132595, 31307, '<td valign="top">I like the title of your photo.  It''s a simple word and a simple concept, but as the photo clearly demonstrates, running a business is often quite hectic.  This clash between simplicity and complexity is portrayed further through your use of black and white.  Great shot.</td>', 'I like the title of your photo.  It''s a simple word and a simple concept, but as the photo clearly demonstrates, running a business is often quite hectic.  This clash between simplicity and complexity is portrayed further through your use of black and white.  Great shot.', '2005-01-04 02:52:38.000000', NULL, 1),
(1090097, 131692, 31307, '<td valign="top">I like that you truncated the mother''s head in this shot.  Though normally a HUGE no-no, in this case I think it is better than to have included it.  For one thing, it allowed you to focus more on the girl by getting a tighter shot rather than be distracted by the presence of another face.</td>', 'I like that you truncated the mother''s head in this shot.  Though normally a HUGE no-no, in this case I think it is better than to have included it.  For one thing, it allowed you to focus more on the girl by getting a tighter shot rather than be distracted by the presence of another face.', '2005-01-04 02:55:22.000000', NULL, 1),
(1090102, 132323, 31307, '<td valign="top">Nice title, I really like it.  However, I have mixed feelings about the fact that the subjects faces are turned away.  Part of me wants to see the faces as a point of interest, but part of me kind of likes how, in not showing their faces completely, you''ve sort of created a veil where they''re in their own private little world because the viewer feels a little detached when he or she can''t relate to the expression on the face.</td>', 'Nice title, I really like it.  However, I have mixed feelings about the fact that the subjects faces are turned away.  Part of me wants to see the faces as a point of interest, but part of me kind of likes how, in not showing their faces completely, you''ve sort of created a veil where they''re in their own private little world because the viewer feels a little detached when he or she can''t relate to the expression on the face.', '2005-01-04 03:00:22.000000', NULL, 1),
(1090108, 132405, 31307, '<td valign="top">I find it...interesting that the green color of the grass is comprised of yellow and blue--the color of the person''s clothing.  Then there''s the orange of the umbrella.  It''s like "Bam!  Orange!  Different!"  I guess it kind of ties into the yellow of the shirt, but still.</td>', 'I find it...interesting that the green color of the grass is comprised of yellow and blue--the color of the person''s clothing.  Then there''s the orange of the umbrella.  It''s like "Bam!  Orange!  Different!"  I guess it kind of ties into the yellow of the shirt, but still.', '2005-01-04 03:07:06.000000', NULL, 1),
(1090111, 132250, 31307, '<td valign="top">Whoa.  As the picture was loading so I could rate it, saw gray/white hair and thought "yeah, looks like an old lady''s hair" but then it got to the skin (you know how it loads from top to bottom) and I say what I thought was..I don''t know...silver makeup?  Don''t ask.  Anyway.  I just thought that black and white was a cool choice for this photo.</td>', 'Whoa.  As the picture was loading so I could rate it, saw gray/white hair and thought "yeah, looks like an old lady''s hair" but then it got to the skin (you know how it loads from top to bottom) and I say what I thought was..I don''t know...silver makeup?  Don''t ask.  Anyway.  I just thought that black and white was a cool choice for this photo.', '2005-01-04 03:10:02.000000', NULL, 1),
(1090113, 132731, 16241, '<td valign="top">which corner?  i''m going :)</td>', 'which corner?  i''m going :)', '2005-01-04 03:11:57.000000', NULL, 1),
(1090114, 132712, 31307, '<td valign="top">Hmmm.  That''s a great looking bridge/background, but I kind of would have liked to be closer to the dad and daughter.  That''s a real tricky one--balancing the two.</td>', 'Hmmm.  That''s a great looking bridge/background, but I kind of would have liked to be closer to the dad and daughter.  That''s a real tricky one--balancing the two.', '2005-01-04 03:12:37.000000', NULL, 1),
(1090117, 132257, 16241, '<td valign="top">what you doing spying on the plumber? :)</td>', 'what you doing spying on the plumber? :)', '2005-01-04 03:15:12.000000', NULL, 1),
(1090121, 131576, 31307, '<td valign="top">Gorgeous shot!  I love the way the people are sihouetted against the sky.  Nice job!</td>', 'Gorgeous shot!  I love the way the people are sihouetted against the sky.  Nice job!', '2005-01-04 03:20:11.000000', NULL, 1),
(1090138, 132074, 30845, '<td valign="top">Great contrasting textures... composition a bit extreme, excessive negative space... great expression, and color.</td>', 'Great contrasting textures... composition a bit extreme, excessive negative space... great expression, and color.', '2005-01-04 04:10:16.000000', NULL, 1),
(1090140, 132718, 30845, '<td valign="top">Brilliant storytelling image</td>', 'Brilliant storytelling image', '2005-01-04 04:11:40.000000', NULL, 1),
(1090141, 131961, 30845, '<td valign="top">Crop seems a bit tight, would like to see more of the setting</td>', 'Crop seems a bit tight, would like to see more of the setting', '2005-01-04 04:12:33.000000', NULL, 1),
(1090143, 132003, 30845, '<td valign="top">Nice sense of scale but lacks depth... subject could be more prominent</td>', 'Nice sense of scale but lacks depth... subject could be more prominent', '2005-01-04 04:13:51.000000', NULL, 1),
(1090145, 132431, 30845, '<td valign="top">Great expressions and gestures... crippling mid-thigh crop... nice shadow exposure</td>', 'Great expressions and gestures... crippling mid-thigh crop... nice shadow exposure', '2005-01-04 04:15:29.000000', NULL, 1),
(1090147, 132881, 30845, '<td valign="top">Great backlight... odd "in-between" moment, something more seems to be happening, perhaps the photographer could''ve waited for the "story" to unfold visually</td>', 'Great backlight... odd "in-between" moment, something more seems to be happening, perhaps the photographer could''ve waited for the "story" to unfold visually', '2005-01-04 04:17:36.000000', NULL, 1),
(1090152, 132492, 30845, '<td valign="top">The tension from the uncertainty of her emotion (sadness? hysterical laughter?) is engaging... weird drop shadow (drag shutter?) effect... odd crop, lots of air at the top: space for the book title??</td>', 'The tension from the uncertainty of her emotion (sadness? hysterical laughter?) is engaging... weird drop shadow (drag shutter?) effect... odd crop, lots of air at the top: space for the book title??', '2005-01-04 04:21:55.000000', NULL, 1),
(1090154, 131708, 30845, '<td valign="top">Great candid... could crop in more</td>', 'Great candid... could crop in more', '2005-01-04 04:24:52.000000', NULL, 1),
(1090157, 132639, 30845, '<td valign="top">The central figure *almost* owns the frame...</td>', 'The central figure *almost* owns the frame...', '2005-01-04 04:26:30.000000', NULL, 1),
(1090158, 131648, 30845, '<td valign="top">The contrast of the white jacket really isolates the subject and reinforces the mood</td>', 'The contrast of the white jacket really isolates the subject and reinforces the mood', '2005-01-04 04:28:09.000000', NULL, 1),
(1090160, 131241, 30845, '<td valign="top">Nice story</td>', 'Nice story', '2005-01-04 04:29:09.000000', NULL, 1),
(1090163, 132522, 30845, '<td valign="top">The magazine steals the show; would like to see more of the subject</td>', 'The magazine steals the show; would like to see more of the subject', '2005-01-04 04:30:04.000000', NULL, 1),
(1090164, 132523, 16266, '<td valign="top">er du norsk eller?.. fin bilde, bra bruk av negative space.. kunne likt a ha mer contrast.</td>', 'er du norsk eller?.. fin bilde, bra bruk av negative space.. kunne likt a ha mer contrast.', '2005-01-04 04:31:49.000000', NULL, 1),
(1090165, 132775, 30845, '<td valign="top">Great expression... exposure a bit hot... avoid from-above perspective on kids, it''s how we see them all the time</td>', 'Great expression... exposure a bit hot... avoid from-above perspective on kids, it''s how we see them all the time', '2005-01-04 04:32:06.000000', NULL, 1),
(1090167, 132626, 30845, '<td valign="top">The glance towards camera changes everything, engages the viewer... wish I could see the whole cart, or at least that he wasn''t running into the left edge of the frame</td>', 'The glance towards camera changes everything, engages the viewer... wish I could see the whole cart, or at least that he wasn''t running into the left edge of the frame', '2005-01-04 04:34:03.000000', NULL, 1),
(1090168, 131832, 30845, '<td valign="top">Hmm... if that''s not candid I don''t know what is</td>', 'Hmm... if that''s not candid I don''t know what is', '2005-01-04 04:34:34.000000', NULL, 1),
(1090170, 131531, 30845, '<td valign="top">Great isolation, too bad we can''t see more of her but the fact that she''s on the phone sort of makes it okay</td>', 'Great isolation, too bad we can''t see more of her but the fact that she''s on the phone sort of makes it okay', '2005-01-04 04:35:54.000000', NULL, 1),
(1090172, 132746, 30845, '<td valign="top">Extra point for cake design  :)</td>', 'Extra point for cake design  :)', '2005-01-04 04:36:34.000000', NULL, 1),
(1090176, 132115, 30845, '<td valign="top">Lose the kid on the right, or, show us more of what they''re both doing or where they are</td>', 'Lose the kid on the right, or, show us more of what they''re both doing or where they are', '2005-01-04 04:40:17.000000', NULL, 1),
(1090194, 132115, 30808, '<td valign="top">good capture!.</td>', 'good capture!.', '2005-01-04 05:16:22.000000', NULL, 1),
(1090222, 131648, 30861, '<td valign="top">clean &amp; sweet, somewhat awkwardly composed to my eye. Lovely profile on the subject. For me it works better as a square crop, top line brought down to exclude the background face.</td>', 'clean & sweet, somewhat awkwardly composed to my eye. Lovely profile on the subject. For me it works better as a square crop, top line brought down to exclude the background face.', '2005-01-04 06:11:50.000000', NULL, 1),
(1090225, 131781, 30861, '<td valign="top">This is very sweet. Perhaps the tonal range could be a tad richer on the subjects themselves. The placement of the profile against the white windbreaker is very nice.</td>', 'This is very sweet. Perhaps the tonal range could be a tad richer on the subjects themselves. The placement of the profile against the white windbreaker is very nice.', '2005-01-04 06:15:56.000000', NULL, 1),
(1090228, 132724, 30861, '<td valign="top">Nice shot. Masybe a bit too much background? Try cropping it down from the top to square? All that receding detail is working against the subject.</td>', 'Nice shot. Masybe a bit too much background? Try cropping it down from the top to square? All that receding detail is working against the subject.', '2005-01-04 06:18:01.000000', NULL, 1),
(1090230, 131712, 30861, '<td valign="top">Damn, that''s...gross? Funny, too. Try burning in the foreground and the bright cushion lower left to contain it a bit?</td>', 'Damn, that''s...gross? Funny, too. Try burning in the foreground and the bright cushion lower left to contain it a bit?', '2005-01-04 06:19:38.000000', NULL, 1),
(1090232, 132900, 30861, '<td valign="top">I''m not sure all this environment is working for you in this shot; it adds little by way of backstory but has many distracting elements. I wish the pole in background weren''t so "behind" the subject, too. A tighter shot might have had more power. Excellent face and hands.</td>', 'I''m not sure all this environment is working for you in this shot; it adds little by way of backstory but has many distracting elements. I wish the pole in background weren''t so "behind" the subject, too. A tighter shot might have had more power. Excellent face and hands.', '2005-01-04 06:22:12.000000', NULL, 1),
(1090234, 131379, 30861, '<td valign="top">I want to like this more than i do; could be a fascinating character study, but the blown-out background higlights are not working for you here.</td>', 'I want to like this more than i do; could be a fascinating character study, but the blown-out background higlights are not working for you here.', '2005-01-04 06:23:30.000000', NULL, 1),
(1090235, 132786, 30861, '<td valign="top">sweet. A little too contrasty, perhaps? nicely composed. Love the paserby''s left hand, seems to be "dismissive"</td>', 'sweet. A little too contrasty, perhaps? nicely composed. Love the paserby''s left hand, seems to be "dismissive"', '2005-01-04 06:24:39.000000', NULL, 1),
(1090236, 132375, 30861, '<td valign="top">Nice to see a cnadid without a face or a body. Pity both hands aren''t sharp., and that we can''t see a tad more of the upper (knife) hand.</td>', 'Nice to see a cnadid without a face or a body. Pity both hands aren''t sharp., and that we can''t see a tad more of the upper (knife) hand.', '2005-01-04 06:26:05.000000', NULL, 1),
(1090238, 132611, 30861, '<td valign="top">A "true" candid. Try doing some work to separate the back of the jacket from the BG?</td>', 'A "true" candid. Try doing some work to separate the back of the jacket from the BG?', '2005-01-04 06:27:11.000000', NULL, 1),
(1090239, 132282, 30861, '<td valign="top">Sweet &amp; evocative. I''d like to see more on bottom here.</td>', 'Sweet & evocative. I''d like to see more on bottom here.', '2005-01-04 06:28:47.000000', NULL, 1),
(1090241, 132840, 30861, '<td valign="top">A somewhat chaotic composition. The faces on the right make the picture.</td>', 'A somewhat chaotic composition. The faces on the right make the picture.', '2005-01-04 06:29:45.000000', NULL, 1),
(1090243, 132276, 30861, '<td valign="top">The murkiness of this, especially when you consider the intense white area at the top, is working against it. I recognize that this murkiness is part of the mood you are after, but I''m having a hard time pulling the subject out of the murk and getting a "read" on him....</td>', 'The murkiness of this, especially when you consider the intense white area at the top, is working against it. I recognize that this murkiness is part of the mood you are after, but I''m having a hard time pulling the subject out of the murk and getting a "read" on him....', '2005-01-04 06:31:34.000000', NULL, 1),
(1090244, 131764, 30861, '<td valign="top">Appealing but kind of pat. The face is a bit blown out.</td>', 'Appealing but kind of pat. The face is a bit blown out.', '2005-01-04 06:32:19.000000', NULL, 1),
(1090245, 132778, 30861, '<td valign="top">would work better for me if you cropped out most of the top and burned down the brighter area upper left. Wht is the face so yellow? I can''t "identify" the source of that light and it makes me uneasy, visually.</td>', 'would work better for me if you cropped out most of the top and burned down the brighter area upper left. Wht is the face so yellow? I can''t "identify" the source of that light and it makes me uneasy, visually.', '2005-01-04 06:34:11.000000', NULL, 1),
