(1092327, 131225, 16636, '<td valign="top">good idea, would have liked to see the person closer to the camera for more impact - 9</td>', 'good idea, would have liked to see the person closer to the camera for more impact - 9', '2005-01-05 07:28:46.000000', NULL, 1),
