(1092333, 131927, 16636, '<td valign="top">well captured moment, the image does seem a little to noisy to me. Good luck -9</td>', 'well captured moment, the image does seem a little to noisy to me. Good luck -9', '2005-01-05 07:30:08.000000', NULL, 1),
(1092335, 131531, 16636, '<td valign="top">good idea nad well exectued - good luck</td>', 'good idea nad well exectued - good luck', '2005-01-05 07:30:30.000000', NULL, 1),
