(1092342, 132074, 16636, '<td valign="top">a stricking image, love the colours and the background enhances the image a lot. good luck</td>', 'a stricking image, love the colours and the background enhances the image a lot. good luck', '2005-01-05 07:32:13.000000', NULL, 1),
(1092459, 131705, 14569, '<td valign="top">Maybe he''s lusting after the kids.  Maybe this should be called ''Thankfully he''ll never sleep with a seven year old again after his ten year jail sentence''</td>', 'Maybe he''s lusting after the kids.  Maybe this should be called ''Thankfully he''ll never sleep with a seven year old again after his ten year jail sentence''', '2005-01-05 08:26:06.000000', NULL, 1),
(1092464, 132003, 14569, '<td valign="top">well then, did she fall?</td>', 'well then, did she fall?', '2005-01-05 08:28:48.000000', NULL, 1),
(1092491, 132605, 30251, '<td valign="top">The post processing makes this difficult to look at. The white shadows in the rocks distract me and they take away from the action of the people. Nice cropping.</td>', 'The post processing makes this difficult to look at. The white shadows in the rocks distract me and they take away from the action of the people. Nice cropping.', '2005-01-05 08:51:57.000000', NULL, 1),
(1092705, 131692, 5822, '<td valign="top">Lighting is wonderful and I like the soft focus as well. Very natural looking colors too. Only thing I can see as a bit distracting is the woman''s watch.</td>', 'Lighting is wonderful and I like the soft focus as well. Very natural looking colors too. Only thing I can see as a bit distracting is the woman''s watch.', '2005-01-05 10:58:49.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1092708, 132482, 5822, '<td valign="top">Technically a good shot, but the clutter on the right half and the fact that I can''t really see what he''s doing detracts from the impact of this image.</td>', 'Technically a good shot, but the clutter on the right half and the fact that I can''t really see what he''s doing detracts from the impact of this image.', '2005-01-05 11:02:10.000000', NULL, 1),
(1092716, 132643, 5822, '<td valign="top">I really like this image but think it''s a tad underexposed as the two figures appear to merge in the blackness of their clothes.</td>', 'I really like this image but think it''s a tad underexposed as the two figures appear to merge in the blackness of their clothes.', '2005-01-05 11:07:54.000000', NULL, 1),
(1092884, 132211, 25754, '<td valign="top">Great night shot but it doesn''t meet the challenge as there are no people in the scene.</td>', 'Great night shot but it doesn''t meet the challenge as there are no people in the scene.', '2005-01-05 13:06:24.000000', NULL, 1),
(1092913, 132639, 25347, '<td valign="top">Outstanding!  I really love this.  Not only is it composed well and an excellent candid, the sepia and clothing make this a timeless image.  You do have some blown highlights, but they hardly distract, rather force the attention onto the man pushing the cart.  One of my favorites of the challenge.</td>', 'Outstanding!  I really love this.  Not only is it composed well and an excellent candid, the sepia and clothing make this a timeless image.  You do have some blown highlights, but they hardly distract, rather force the attention onto the man pushing the cart.  One of my favorites of the challenge.', '2005-01-05 13:19:33.000000', NULL, 1),
(1092918, 132106, 11738, '<td valign="top">Interesting picture.  Too bad you couldn''t have submitted one of the lady not making a funny face.  Good composition</td>', 'Interesting picture.  Too bad you couldn''t have submitted one of the lady not making a funny face.  Good composition', '2005-01-05 13:21:18.000000', NULL, 1),
(1092927, 132712, 25347, '<td valign="top">Hey, wait a minute, those aren''t monkies!  I love th ecolors in this, however I sort of feel that because of the composition, the bridge is being presented as teh subject rather than the people.  perhaps a lower angle, and maybe getting cloer to the subject would''ve worked (though the latter was probably impossible because of the water).  I do like how the bridge is framed, and I like the mountains/hills in the background.  Maybe even if you''d''ve panned lower to include more of the water in the foreground, thus moving the bridge to the top and focusing on the pair, but I dunno.  Nevertheless, a good shot.</td>', 'Hey, wait a minute, those aren''t monkies!  I love th ecolors in this, however I sort of feel that because of the composition, the bridge is being presented as teh subject rather than the people.  perhaps a lower angle, and maybe getting cloer to the subject would''ve worked (though the latter was probably impossible because of the water).  I do like how the bridge is framed, and I like the mountains/hills in the background.  Maybe even if you''d''ve panned lower to include more of the water in the foreground, thus moving the bridge to the top and focusing on the pair, but I dunno.  Nevertheless, a good shot.', '2005-01-05 13:23:15.000000', NULL, 1),
(1092932, 131760, 11738, '<td valign="top">Nice picture of an old fella.  Can''t make up my mind if he''s looking at you (not a candid) or just to your right (a candid).  The soft focus is a nice touch.  Good lighting too although almost blown out on the front of his shirt.</td>', 'Nice picture of an old fella.  Can''t make up my mind if he''s looking at you (not a candid) or just to your right (a candid).  The soft focus is a nice touch.  Good lighting too although almost blown out on the front of his shirt.', '2005-01-05 13:24:44.000000', NULL, 1),
(1092940, 131238, 11738, '<td valign="top">LOL!  What a funny picture.  Technically needs a little more, but very cool.</td>', 'LOL!  What a funny picture.  Technically needs a little more, but very cool.', '2005-01-05 13:28:21.000000', NULL, 1),
(1092945, 132523, 25347, '<td valign="top">You have an extremely interesting subject here, but I have no idea what he''s doing; what the right side of his face looks like; or where he is.  It appears as though you''ve captured some good details in his face, but there''s too much negative space (the subject is too small) to see them, and I''m sure they''re most definitely interesting.  This image has great potential and a wonderful subject; however I feel there''s so much more this image could do... creating a story, giving me an insight to who he is, what he''s doing, where he is... and this image comes short there.</td>', 'You have an extremely interesting subject here, but I have no idea what he''s doing; what the right side of his face looks like; or where he is.  It appears as though you''ve captured some good details in his face, but there''s too much negative space (the subject is too small) to see them, and I''m sure they''re most definitely interesting.  This image has great potential and a wonderful subject; however I feel there''s so much more this image could do... creating a story, giving me an insight to who he is, what he''s doing, where he is... and this image comes short there.', '2005-01-05 13:29:11.000000', NULL, 1),
(1092954, 131965, 11738, '<td valign="top">A few problems with this one: i) image too small, ii) red seems oversaturated (their fingers and glass of juice), and iii) they''re both looking straight at the photographer.  I may be interpreting the concept wrong, but I always thought that a candid shot was one where the person(s) did not know they were being photographed.</td>', 'A few problems with this one: i) image too small, ii) red seems oversaturated (their fingers and glass of juice), and iii) they''re both looking straight at the photographer.  I may be interpreting the concept wrong, but I always thought that a candid shot was one where the person(s) did not know they were being photographed.', '2005-01-05 13:32:16.000000', NULL, 1),
(1092963, 131705, 14614, '<td valign="top">nice job of pulling the main subjects out and blurring the background -- extra effort pays off in a stronger composition</td>', 'nice job of pulling the main subjects out and blurring the background -- extra effort pays off in a stronger composition', '2005-01-05 13:35:07.000000', NULL, 1),
(1092972, 132692, 11738, '<td valign="top">Interesting statue, but how can a shot of a statue be candid?  To be candid I think the thing your are photographing has to be sentient, a living, breathing entity.  Technically this photo is quite good.  Nice shallow DOF and great lighting.  I like how the eyes are slightly darker than the rest of the face.  Pretty good bokeh (our word of the week) too.<br/> <br/>EDITed for spelling<br/><br/><i>Message edited by author 2005-01-12 08:31:06.</i></td>', 'Interesting statue, but how can a shot of a statue be candid?  To be candid I think the thing your are photographing has to be sentient, a living, breathing entity.  Technically this photo is quite good.  Nice shallow DOF and great lighting.  I like how the eyes are slightly darker than the rest of the face.  Pretty good bokeh (our word of the week) too. EDITed for spelling', '2005-01-05 13:39:22.000000', '2005-01-12 08:31:06.000000', 1),
(1092990, 132854, 25347, '<td valign="top">A very busy image, but I''m sure that was your intent, to present a scene that would confuse anyone, becoming bewildered and lost.  All in all, this image fulfills its purpose, but I think there''s some things where it could improve.<br/> <br/>Firstly: the title is "Where to Shop Next?" yet the three subjects appear to be admiring the decorations and elavators.  I''m not sure if this was available to you, but perhaps a location change would''ve been more suitable: I like the tiered effect very much, however no storefronts appear.  Maybe increasing the frame more so that bright neon signs are presented everywhere one looks.  That would help implement the effect of bewilderness I think you''re going for.  I know when I go to malls, I''m intimidated by all the different storefronts and signs that are literally everywhere (which is why I don''t go to the mall much... heh)<br/> <br/>Secondly: I covered this a little before, but the image doesn''t quite match the title.  The subjects don''t really appear exhausted from storehopping, and there''s no shops in the image.  Also, the elevator complex appears to be holding all of their attention.<br/> <br/>Thirdly: I know it was candid, so this probably was a factor out of your control, but the subjects aren''t really fitting for this image, in my opinion.  I think what would''ve been a better subject is a man, a plethora of shopping bags in both hands, looking exhausted, surveying the scene I mentioned earlier, an overwhelming display of neon signs and storefronts.  I think personally that women are immune to the bewilderment I experience at malls.  But that''s a whole nother topic.<br/> <br/>Forthly (and Lastly):  Just a bit of technical stuff, but their feet are cut off and the railing seems a bit crooked.  Also, they seem like thy''re too far away and don''t hold much presence to be the subject.  I''m more drawn to the red and green present more in the middle.  Perhaps taking it on the same level as the subject, as to provide a view of stoorfromts, complex decorations, and a subject with more holding power.<br/> <br/>Hopefully that was helpful... I tried to keep it short ; )</td>', 'A very busy image, but I''m sure that was your intent, to present a scene that would confuse anyone, becoming bewildered and lost.  All in all, this image fulfills its purpose, but I think there''s some things where it could improve. Firstly: the title is "Where to Shop Next?" yet the three subjects appear to be admiring the decorations and elavators.  I''m not sure if this was available to you, but perhaps a location change would''ve been more suitable: I like the tiered effect very much, however no storefronts appear.  Maybe increasing the frame more so that bright neon signs are presented everywhere one looks.  That would help implement the effect of bewilderness I think you''re going for.  I know when I go to malls, I''m intimidated by all the different storefronts and signs that are literally everywhere (which is why I don''t go to the mall much... heh) Secondly: I covered this a little before, but the image doesn''t quite match the title.  The subjects don''t really appear exhausted from storehopping, and there''s no shops in the image.  Also, the elevator complex appears to be holding all of their attention. Thirdly: I know it was candid, so this probably was a factor out of your control, but the subjects aren''t really fitting for this image, in my opinion.  I think what would''ve been a better subject is a man, a plethora of shopping bags in both hands, looking exhausted, surveying the scene I mentioned earlier, an overwhelming display of neon signs and storefronts.  I think personally that women are immune to the bewilderment I experience at malls.  But that''s a whole nother topic. Forthly (and Lastly):  Just a bit of technical stuff, but their feet are cut off and the railing seems a bit crooked.  Also, they seem like thy''re too far away and don''t hold much presence to be the subject.  I''m more drawn to the red and green present more in the middle.  Perhaps taking it on the same level as the subject, as to provide a view of stoorfromts, complex decorations, and a subject with more holding power. Hopefully that was helpful... I tried to keep it short ; )', '2005-01-05 13:43:54.000000', NULL, 1),
(1093000, 132626, 11738, '<td valign="top">He''s looking right at you: in my book that''s not a candid.  Good B&amp;W treatment.</td>', 'He''s looking right at you: in my book that''s not a candid.  Good B&W treatment.', '2005-01-05 13:46:35.000000', NULL, 1),
(1093001, 131832, 25347, '<td valign="top">Aww man.....  talk about the dire lack of dignity in an image ; )<br/> <br/>Technically, its good.  Well framed, good composition.  I might have liked to see a tighter crop on the left, but then you''d cut out the shadow, so really I''m torn.  I''m not sure if I like the bit of yellow on the border.. I think maybe white would''ve served better for the purpose.  Good technical image, but otherwise, I''m disgusted :Þ<br/> <br/>But I won''t let that affect my vote.</td>', 'Aww man.....  talk about the dire lack of dignity in an image ; ) Technically, its good.  Well framed, good composition.  I might have liked to see a tighter crop on the left, but then you''d cut out the shadow, so really I''m torn.  I''m not sure if I like the bit of yellow on the border.. I think maybe white would''ve served better for the purpose.  Good technical image, but otherwise, I''m disgusted :Þ But I won''t let that affect my vote.', '2005-01-05 13:46:42.000000', NULL, 1),
(1093033, 132442, 25347, '<td valign="top">sometimes selective desaturation can do a marvelous job in drawing the focus of an image to one certain thing that is the key element of a photo that would be sadly overlooked or underrecognized in the full color version.<br/> <br/>In my opinion, this isn''t one of those times.<br/> <br/>Though I have no grasp on what the color version looks like, I can almost assuredly say that this imsage is so simple in its composition that it doesn''t need selective desaturation.  I think that the selective desaturation in this image actually hurts it, because the challenge subject is candid, however all color has been drained from the alleged subject, drawing the focus to the bubble wand (or whatever you call those crazy things).  Not only that, but the bubble wand, without the title, is unrecognizable.  Without seeing the title, I originally thought it was some sort of lollypop dripping with his spit.  Also, the border detracts from the image.  With the light qualities of this, the black border doesn''t help.  When you''re doing a shot this close, its best to keep it as simple as possible, and the selective desat and border, in my opinion, detract from that.  And a few technical things, too: blown hilights, the image is slightly tilted, judging by the structure in the background.  But those things don''t really concern me as much as the desat and the border.</td>', 'sometimes selective desaturation can do a marvelous job in drawing the focus of an image to one certain thing that is the key element of a photo that would be sadly overlooked or underrecognized in the full color version. In my opinion, this isn''t one of those times. Though I have no grasp on what the color version looks like, I can almost assuredly say that this imsage is so simple in its composition that it doesn''t need selective desaturation.  I think that the selective desaturation in this image actually hurts it, because the challenge subject is candid, however all color has been drained from the alleged subject, drawing the focus to the bubble wand (or whatever you call those crazy things).  Not only that, but the bubble wand, without the title, is unrecognizable.  Without seeing the title, I originally thought it was some sort of lollypop dripping with his spit.  Also, the border detracts from the image.  With the light qualities of this, the black border doesn''t help.  When you''re doing a shot this close, its best to keep it as simple as possible, and the selective desat and border, in my opinion, detract from that.  And a few technical things, too: blown hilights, the image is slightly tilted, judging by the structure in the background.  But those things don''t really concern me as much as the desat and the border.', '2005-01-05 13:58:03.000000', NULL, 1),
(1093047, 131094, 25347, '<td valign="top">Argh, the little buggers try and eat out of our birdfeeder too!.  Brilliant squirrel picture however it feels to me when looking at this that the image is too heavy in the bottom left.  Maybe a little farther away with the squirrel centered in the image would''ve been nicer, unless there''s something that would''ve thrown off the bokeh (heh, I just learned that word this week and I''m already throwing it around :D) that you cropped out on purpose.  I love the clarity here.  To solve the problem, we have a little squirrel catcher around the pole supporting the feeder, as well as live animal traps around the bottom. ; )</td>', 'Argh, the little buggers try and eat out of our birdfeeder too!.  Brilliant squirrel picture however it feels to me when looking at this that the image is too heavy in the bottom left.  Maybe a little farther away with the squirrel centered in the image would''ve been nicer, unless there''s something that would''ve thrown off the bokeh (heh, I just learned that word this week and I''m already throwing it around :D) that you cropped out on purpose.  I love the clarity here.  To solve the problem, we have a little squirrel catcher around the pole supporting the feeder, as well as live animal traps around the bottom. ; )', '2005-01-05 14:02:53.000000', NULL, 1),
