(1097012, 131865, 28261, '<td valign="top">A slight rotation to pure vertical the pole would go a long way to putting a finishing touch on this shot.  It seems selectively desaturated which I like, but wonder if the impact would have been more striking if you had left all colorized except for the sign holder.  With him in the stark black and white, it would lend well to editorial commentary.  A bit dark, and the walkman wearer in the background is a bit distracting, but overall a great capture.  7</td>', 'A slight rotation to pure vertical the pole would go a long way to putting a finishing touch on this shot.  It seems selectively desaturated which I like, but wonder if the impact would have been more striking if you had left all colorized except for the sign holder.  With him in the stark black and white, it would lend well to editorial commentary.  A bit dark, and the walkman wearer in the background is a bit distracting, but overall a great capture.  7', '2005-01-08 11:58:06.000000', NULL, 1),
(1097015, 132233, 31244, '<td valign="top">Too small for me..</td>', 'Too small for me..', '2005-01-08 11:58:11.000000', NULL, 1),
