(1097017, 132786, 31244, '<td valign="top">This is my favorite for the challenge. The expression on the man''s face and the hand motion of the city dweller all add to the uniquness of this photo. Good job! 10!</td>', 'This is my favorite for the challenge. The expression on the man''s face and the hand motion of the city dweller all add to the uniquness of this photo. Good job! 10!', '2005-01-08 11:59:44.000000', NULL, 1),
(1097021, 132873, 28261, '<td valign="top">A little too light on the face for me, but otherwise a great image.  I like the beveled edge effect before the border as it seems to push the eye inward.  Could use a slight counterclockwsie rotation to line up the posts and windows.  Their alignment seems to cause a slight falling effect towards the right and tips the balance a bit too heavily.  a 7.</td>', 'A little too light on the face for me, but otherwise a great image.  I like the beveled edge effect before the border as it seems to push the eye inward.  Could use a slight counterclockwsie rotation to line up the posts and windows.  Their alignment seems to cause a slight falling effect towards the right and tips the balance a bit too heavily.  a 7.', '2005-01-08 12:02:10.000000', NULL, 1),
(1097024, 132847, 26151, '<td valign="top">Would have a great photo if the focus was a little better. The left shoulder and staff patch seems to be more in focus then the face and the bird.</td>', 'Would have a great photo if the focus was a little better. The left shoulder and staff patch seems to be more in focus then the face and the bird.', '2005-01-08 12:03:10.000000', NULL, 1),
(1097025, 132634, 28261, '<td valign="top">Bumping this up to a 9.  The colors are perfect and the desaturation of the rest puts all focus on the subject and the excited expression.  Simple, focused and candid.  Great!</td>', 'Bumping this up to a 9.  The colors are perfect and the desaturation of the rest puts all focus on the subject and the excited expression.  Simple, focused and candid.  Great!', '2005-01-08 12:03:57.000000', NULL, 1),
