INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1101156, 131382, 14656, '<td valign="top">Was really looking forwared to this challenge but was plagued with bad weather during submission week so my chances for capturing a great candid was severely limited (no opportunities at home). Submitted this shot as a "backup" in case I did not catch anything else... which I didn''t. This was the closest image to a candid I shot all week, the rest of my images were landscapes devoid of people.<br/> <br/>Thanks to those that commented. This entry generated some of the best comments I''ve received on DPC to date!</td>', 'Was really looking forwared to this challenge but was plagued with bad weather during submission week so my chances for capturing a great candid was severely limited (no opportunities at home). Submitted this shot as a "backup" in case I did not catch anything else... which I didn''t. This was the closest image to a candid I shot all week, the rest of my images were landscapes devoid of people. Thanks to those that commented. This entry generated some of the best comments I''ve received on DPC to date!', '2005-01-11 07:36:19.000000', NULL, 0),
(1101198, 131927, 7907, '<td valign="top">This is such a beautiful shot!  It reminds me of the pure happiness I felt when my grandmother smiled at me that way.  Well done!</td>', 'This is such a beautiful shot!  It reminds me of the pure happiness I felt when my grandmother smiled at me that way.  Well done!', '2005-01-11 08:35:43.000000', NULL, 0),
(1101201, 132634, 15711, '<td valign="top">Congratulations.  Well done and surely a winner in my book.</td>', 'Congratulations.  Well done and surely a winner in my book.', '2005-01-11 08:41:34.000000', NULL, 0),
(1101583, 131380, 2764, '<td valign="top">Hey - if the Wonderdog needs a new vet, my sister is in Brewster - Dr. Morgan.</td>', 'Hey - if the Wonderdog needs a new vet, my sister is in Brewster - Dr. Morgan.', '2005-01-11 12:03:48.000000', NULL, 0),
(1101589, 131250, 20774, '<td valign="top">Great shot. Just love the moment, it seems like theres gonna be trouble since the kid is just pointing out something. Just don''t stop, would love to see more of these guys! :)</td>', 'Great shot. Just love the moment, it seems like theres gonna be trouble since the kid is just pointing out something. Just don''t stop, would love to see more of these guys! :)', '2005-01-11 12:12:38.000000', NULL, 0),
